    /** @type {Record<string, { id: string|number, meta: object, sizeBytes: number, downloadedAt: number }>} */
    downloaded: {},
    /** @type {Record<string, { status: 'queued'|'downloading'|'error', pct: number, error?: string }>} */
    progress: {},
    wifiOnly: loadWifiOnly(),
    totalBytes: 0,
    hydrated: false,
    hydrating: false,
    /** playlist download job */
    playlistJob: null,
  }),

  getters: {
    downloadedList: (state) =>
      Object.values(state.downloaded).sort(
        (a, b) => (b.downloadedAt || 0) - (a.downloadedAt || 0),
      ),
    downloadedCount: (state) => Object.keys(state.downloaded).length,
    isDownloaded: (state) => (trackId) => Boolean(state.downloaded[String(trackId)]),
    getProgress: (state) => (trackId) => state.progress[String(trackId)] || null,
  },

  actions: {
    async hydrate() {
      if (this.hydrated || this.hydrating) return
      this.hydrating = true
      try {
        const rows = await offlineDb.listTracks()
        /** @type {Record<string, object>} */
        const map = {}
        let total = 0
        for (const row of rows) {
          const key = String(row.id)
          map[key] = {
            id: row.id,
            meta: row.meta,
            sizeBytes: row.sizeBytes || 0,
            downloadedAt: row.downloadedAt || 0,
          }
          total += row.sizeBytes || 0
        }
        this.downloaded = map
        this.totalBytes = total
        this.hydrated = true
      } catch (err) {
        console.warn('[offline] hydrate failed', err)
      } finally {
        this.hydrating = false
      }
    },

    setWifiOnly(value) {
      this.wifiOnly = Boolean(value)
      localStorage.setItem(WIFI_ONLY_STORAGE_KEY, this.wifiOnly ? 'true' : 'false')
    },

    isDownloadable(track) {
      return isTrackDownloadable(track)
    },

    /**
     * @returns {{ ok: true }|{ ok: false, reason: 'wifi'|'offline' }}
     */
    canStartDownload() {
      if (typeof navigator !== 'undefined' && navigator.onLine === false) {
        return { ok: false, reason: 'offline' }
      }
      if (this.wifiOnly && isCellularConnection()) {
        return { ok: false, reason: 'wifi' }
      }
      return { ok: true }
    },

    /**
     * @param {object} track
     * @param {{ silent?: boolean }} [opts]
     */
    async downloadTrack(track, opts = {}) {
      if (!track?.id) return { ok: false, reason: 'invalid' }

      const key = String(track.id)
      if (this.downloaded[key]) return { ok: true, already: true }

      if (!isTrackDownloadable(track)) {
        if (!opts.silent) {
          notifyDark({ type: 'warning', message: OFFLINE_COPY.err.linked })
        }
        return { ok: false, reason: 'linked' }
      }

      const gate = this.canStartDownload()
      if (!gate.ok) {
        if (!opts.silent) {
          notifyDark({
            type: 'warning',
            message: gate.reason === 'wifi' ? OFFLINE_COPY.err.wifiOnly : OFFLINE_COPY.err.mutation,
          })
        }
        return { ok: false, reason: gate.reason }
      }

      const streamUrl = toEngineProxyUrl(track.stream_url)
      if (!streamUrl) {
        return { ok: false, reason: 'no-stream' }
      }

      const estimatedNeed = track.size || 0
      if (estimatedNeed > 0) {
        const est = await offlineDb.estimateStorage()
        if (est && est.quota > 0) {
          const remaining = est.quota - est.usage
          if (estimatedNeed > remaining) {
            if (!opts.silent) {
              notifyDark({ type: 'negative', message: OFFLINE_COPY.err.storageFull })
            }
            return { ok: false, reason: 'storage' }
          }
        }
      }

      this.progress = {
        ...this.progress,
        [key]: { status: 'downloading', pct: 0 },
      }

      try {
        const token =
          typeof localStorage !== 'undefined' ? localStorage.getItem('max_tune_token') : null
        const headers = {
          Accept: '*/*',
          'X-Requested-With': 'XMLHttpRequest',
        }
        if (token) headers.Authorization = `Bearer ${token}`

        const res = await fetch(streamUrl, {
          method: 'GET',
          headers,
          credentials: 'same-origin',
        })

        if (!res.ok) {
          throw new Error(`Download failed (${res.status})`)
        }

        const contentLength = Number(res.headers.get('content-length') || 0)
        const reader = res.body?.getReader()
        /** @type {Uint8Array[]} */
        const chunks = []
        let received = 0

        if (reader) {
          for (;;) {
            const { done, value } = await reader.read()
            if (done) break
            chunks.push(value)
            received += value.byteLength
            const total = contentLength || track.size || 0
            const pct = total ? Math.min(99, Math.round((received / total) * 100)) : 0
            this.progress = {
              ...this.progress,
              [key]: { status: 'downloading', pct },
            }
          }
        } else {
          const buf = await res.arrayBuffer()
          chunks.push(new Uint8Array(buf))
          received = buf.byteLength
        }

        const mime = res.headers.get('content-type') || track.mime || 'audio/mpeg'
        const audioBlob = new Blob(chunks, { type: mime })
        const sizeBytes = audioBlob.size

        /** @type {Blob|null} */
        let coverBlob = null
        const coverUrl = toEngineProxyUrl(track.cover_url)
        if (coverUrl) {
          try {
            const coverRes = await fetch(coverUrl, {
              headers: token ? { Authorization: `Bearer ${token}` } : {},
              credentials: 'same-origin',
            })
            if (coverRes.ok) coverBlob = await coverRes.blob()
          } catch {
            // optional cover — ignore
          }
        }

        const meta = {
          id: track.id,
          title: track.title,
          artist_name: track.artist_name,
          album_name: track.album_name,
          duration_ms: track.duration_ms,
          mime: track.mime || mime,
          size: sizeBytes,
          source: track.source,
          import_mode: track.import_mode,
          liked: track.liked,
          cover_url: track.cover_url,
          stream_url: track.stream_url,
        }

        await offlineDb.putTrack({
          id: track.id,
          meta,
          audioBlob,
          coverBlob,
          sizeBytes,
          downloadedAt: Date.now(),
        })

        this.downloaded = {
          ...this.downloaded,
          [key]: {
            id: track.id,
            meta,
            sizeBytes,
            downloadedAt: Date.now(),
          },
        }
        this.totalBytes = Object.values(this.downloaded).reduce(
          (s, row) => s + (row.sizeBytes || 0),
          0,
        )

        const nextProgress = { ...this.progress }
        delete nextProgress[key]
        this.progress = nextProgress

        return { ok: true, sizeBytes }
      } catch (err) {
        const message = err?.name === 'QuotaExceededError' ? OFFLINE_COPY.err.storageFull : null
        this.progress = {
          ...this.progress,
          [key]: {
            status: 'error',
            pct: 0,
            error: message || err?.message || 'failed',
          },
        }
        if (!opts.silent) {
          notifyDark({
            type: 'negative',
            message: message || OFFLINE_COPY.err.downloadFail,
          })
        }
        return {
          ok: false,
          reason: message ? 'storage' : 'error',
          error: err,
        }
      }
    },

    /**
     * @param {object[]} tracks
     * @param {{ playlistId?: string|number }} [opts]
     */
    async downloadPlaylist(tracks, opts = {}) {
      const list = Array.isArray(tracks) ? tracks : []
      const downloadable = list.filter((t) => isTrackDownloadable(t) && !this.downloaded[String(t.id)])
      const already = list.filter((t) => this.downloaded[String(t.id)])
      const skipped = list.filter((t) => !isTrackDownloadable(t))

      const aboutBytes = downloadable.reduce((s, t) => s + (t.size || 0), 0)
      if (aboutBytes > 0) {
        const est = await offlineDb.estimateStorage()
        if (est && est.quota > 0 && aboutBytes > est.quota - est.usage) {
          notifyDark({ type: 'negative', message: OFFLINE_COPY.err.storageFull })
          return {
            ok: false,
            reason: 'storage',
            skipped: skipped.length,
            done: 0,
            total: downloadable.length,
          }
        }
      }

      const gate = this.canStartDownload()
      if (!gate.ok) {
        notifyDark({
          type: 'warning',
          message: gate.reason === 'wifi' ? OFFLINE_COPY.err.wifiOnly : OFFLINE_COPY.err.mutation,
        })
        return { ok: false, reason: gate.reason, skipped: skipped.length }
      }

      this.playlistJob = {
        playlistId: opts.playlistId ?? null,
        done: already.length,
        total: downloadable.length + already.length,
        skipped: skipped.length,
        status: 'running',
        aboutBytes: aboutBytes + already.reduce((s, t) => s + (this.downloaded[String(t.id)]?.sizeBytes || 0), 0),
      }

      let succeeded = already.length
      for (const track of downloadable) {
        const result = await this.downloadTrack(track, { silent: true })
        if (result.ok) {
          succeeded += 1
        } else if (result.reason === 'storage' || result.reason === 'wifi') {
          break
        }
        this.playlistJob = {
          ...this.playlistJob,
          done: succeeded,
          status: 'running',
        }
      }

      this.playlistJob = {
        ...this.playlistJob,
        done: succeeded,
        status: 'done',
        skipped: skipped.length,
      }

      return {
        ok: true,
        done: succeeded,
        total: downloadable.length + already.length,
        skipped: skipped.length,
      }
    },

    clearPlaylistJob() {
      this.playlistJob = null
    },

    /**
     * @param {number|string} trackId
     * @returns {Promise<string|null>} object URL
     */
    async getLocalBlobUrl(trackId) {
      const key = String(trackId)
      if (blobUrls.has(key)) return blobUrls.get(key)

      const row = await offlineDb.getTrack(trackId)
      if (!row?.audioBlob) return null

      const url = URL.createObjectURL(row.audioBlob)
      blobUrls.set(key, url)
      return url
    },

    /**
     * @param {number|string} trackId
     * @returns {Promise<object|null>}
     */
    async getLocalMeta(trackId) {
      const cached = this.downloaded[String(trackId)]
      if (cached?.meta) return cached.meta
      const row = await offlineDb.getTrack(trackId)
      return row?.meta || null
    },

    revokeBlobUrl(trackId) {
      const key = String(trackId)
      const url = blobUrls.get(key)
      if (url) {
        URL.revokeObjectURL(url)
        blobUrls.delete(key)
      }
    },

    async removeTrack(trackId) {
      const key = String(trackId)
      this.revokeBlobUrl(trackId)
      await offlineDb.deleteTrack(trackId)
      const next = { ...this.downloaded }
      delete next[key]
      this.downloaded = next
      const nextProgress = { ...this.progress }
      delete nextProgress[key]
      this.progress = nextProgress
      this.totalBytes = Object.values(this.downloaded).reduce(
        (s, row) => s + (row.sizeBytes || 0),
        0,
      )
    },

    /**
     * @param {object[]} tracks
     */
    async removePlaylistDownloads(tracks) {
      const list = Array.isArray(tracks) ? tracks : []
      for (const t of list) {
        if (this.downloaded[String(t.id)]) {
          await this.removeTrack(t.id)
        }
      }
    },

    async removeAll() {
      for (const key of blobUrls.keys()) {
        this.revokeBlobUrl(key)
      }
      await offlineDb.clearAll()
      this.downloaded = {}
      this.progress = {}
      this.totalBytes = 0
      this.playlistJob = null
    },

    /**
     * Estimate about-bytes for a playlist (downloadable + already cached).
     * @param {object[]} tracks
     */
    estimatePlaylistBytes(tracks) {
      const list = Array.isArray(tracks) ? tracks : []
      let bytes = 0
      for (const t of list) {
        if (!isTrackDownloadable(t)) continue
        const cached = this.downloaded[String(t.id)]
        bytes += cached?.sizeBytes || t.size || 0
      }
      return bytes
    },
  },
})

import { defineStore } from 'pinia'
import { Notify } from 'quasar'
import { OFFLINE_COPY } from '@/constants/offline-copy'
import { toEngineProxyUrl } from '@/helpers/mediaUrl'
import { useOfflineStore } from '@/stores/offline-store'
import { isAppOffline } from '@/composables/useConnectivity'

/** @type {HTMLAudioElement|null} */
let audioEl = null

/** Prevent infinite stream↔local fallback loops */
let fallbackAttemptedFor = null

/**
 * Module-scoped audio keeps playing across SPA navigations.
 * Phase 1.1: never pause from visibilitychange / blur / pagehide alone.
 */
function getAudio() {
  if (typeof window === 'undefined') return null
  if (!audioEl) {
    audioEl = new Audio()
    audioEl.preload = 'metadata'
    audioEl.crossOrigin = 'anonymous'
    audioEl.setAttribute('data-maxtune-audio', '1')
    audioEl.style.display = 'none'
    if (document.body) {
      document.body.appendChild(audioEl)
    } else {
      document.addEventListener(
        'DOMContentLoaded',
        () => {
          if (audioEl && !audioEl.isConnected) document.body.appendChild(audioEl)
        },
        { once: true },
      )
    }
  } else if (document.body && !audioEl.isConnected) {
    document.body.appendChild(audioEl)
  }
  return audioEl
}

const ARTWORK_SIZES = [96, 128, 192, 256, 384, 512]

function buildArtwork(coverUrl) {
  if (!coverUrl) return []
  return ARTWORK_SIZES.map((size) => ({
    src: coverUrl,
    sizes: `${size}x${size}`,
    type: 'image/jpeg',
  }))
}

function hasMediaSession() {
  return typeof navigator !== 'undefined' && 'mediaSession' in navigator
}

function isBrowserOrEngineOffline() {
  return isAppOffline()
}

function notifyPlayOffline() {
  Notify.create({
    type: 'negative',
    message: OFFLINE_COPY.err.playOffline,
    caption: OFFLINE_COPY.err.playOfflineHint,
    position: 'top',
    timeout: 3500,
  })
}

export const usePlayerStore = defineStore('player', {
  state: () => ({
    currentTrack: null,
    queue: [],
    isPlaying: false,
    shuffle: false,
    repeat: 'off', // off | one | all
    positionMs: 0,
    durationMs: 0,
    volume: 0.9,
    bufferedPct: 0,
    error: null,
    sheetOpen: false,
    playingFromLocal: false,
    _bound: false,
    _mediaSessionBound: false,
  }),

  getters: {
    hasTrack: (state) => Boolean(state.currentTrack),
    displayTitle: (state) => state.currentTrack?.title || 'Nothing playing',
    displayArtist: (state) => state.currentTrack?.artist_name || '—',
    coverUrl: (state) => toEngineProxyUrl(state.currentTrack?.cover_url),
    progressPct: (state) => {
      if (!state.durationMs) return 0
      return Math.min(100, (state.positionMs / state.durationMs) * 100)
    },
  },

  actions: {
    openSheet() {
      if (this.hasTrack) this.sheetOpen = true
    },

    closeSheet() {
      this.sheetOpen = false
    },

    bindAudioEvents() {
      if (this._bound) return
      const audio = getAudio()
      if (!audio) return

      audio.volume = this.volume

      audio.addEventListener('timeupdate', () => {
        this.positionMs = Math.round(audio.currentTime * 1000)
        if (audio.buffered.length) {
          const end = audio.buffered.end(audio.buffered.length - 1)
          this.bufferedPct = audio.duration ? (end / audio.duration) * 100 : 0
        }
        this.updateMediaSessionPosition()
      })

      audio.addEventListener('loadedmetadata', () => {
        this.durationMs = Math.round((audio.duration || 0) * 1000)
        this.updateMediaSessionPosition()
      })

      audio.addEventListener('play', () => {
        this.isPlaying = true
        this.syncMediaSessionPlaybackState()
      })

      audio.addEventListener('pause', () => {
        this.isPlaying = false
        this.syncMediaSessionPlaybackState()
      })

      audio.addEventListener('ended', () => {
        if (this.repeat === 'one') {
          audio.currentTime = 0
          audio.play().catch(() => {})
          return
        }
        this.isPlaying = false
        this.positionMs = 0
        this.playNext({ auto: true })
      })

      audio.addEventListener('error', () => {
        this.handlePlaybackError().catch(() => {})
      })

      this._bound = true
      this.bindMediaSessionHandlers()
    },

    /**
     * Auto-fallback: online stream fail → local blob once (O4).
     */
    async handlePlaybackError() {
      const track = this.currentTrack
      if (!track) {
        this.isPlaying = false
        this.error = 'Playback failed'
        this.syncMediaSessionPlaybackState()
        return
      }

      const trackKey = String(track.id)
      if (fallbackAttemptedFor === trackKey || this.playingFromLocal) {
        this.isPlaying = false
        this.error = 'Playback failed'
        this.syncMediaSessionPlaybackState()
        return
      }

      const offline = useOfflineStore()
      if (!offline.isDownloaded(track.id)) {
        this.isPlaying = false
        this.error = 'Playback failed'
        this.syncMediaSessionPlaybackState()
        return
      }

      fallbackAttemptedFor = trackKey
      const ok = await this.playFromLocal(track)
      if (!ok) {
        this.isPlaying = false
        this.error = 'Playback failed'
        this.syncMediaSessionPlaybackState()
      }
    },

    bindMediaSessionHandlers() {
      if (this._mediaSessionBound || !hasMediaSession()) return

      const ms = navigator.mediaSession
      try {
        ms.setActionHandler('play', () => {
          this.resumeFromMediaSession().catch(() => {})
        })
        ms.setActionHandler('pause', () => {
          const audio = getAudio()
          if (audio && !audio.paused) audio.pause()
        })
        ms.setActionHandler('previoustrack', () => {
          this.playPrev().catch(() => {})
        })
        ms.setActionHandler('nexttrack', () => {
          this.playNext().catch(() => {})
        })
        ms.setActionHandler('seekto', (details) => {
          const audio = getAudio()
          if (!audio || !audio.duration) return
          if (details.fastSeek && typeof audio.fastSeek === 'function') {
            audio.fastSeek(details.seekTime)
          } else if (typeof details.seekTime === 'number') {
            audio.currentTime = details.seekTime
          }
          this.positionMs = Math.round(audio.currentTime * 1000)
          this.updateMediaSessionPosition()
        })
      } catch {
        // Some handlers unsupported on certain platforms — ignore.
      }

      this._mediaSessionBound = true
    },

    updateMediaSessionMetadata() {
      if (!hasMediaSession()) return
      const track = this.currentTrack
      if (!track) {
        try {
          navigator.mediaSession.metadata = null
          navigator.mediaSession.playbackState = 'none'
        } catch {
          // ignore
        }
        return
      }

      const cover = this.coverUrl
      try {
        navigator.mediaSession.metadata = new MediaMetadata({
          title: track.title || 'Unknown title',
          artist: track.artist_name || 'Unknown artist',
          album: track.album_name || 'MaxTune',
          artwork: buildArtwork(cover),
        })
      } catch {
        try {
          navigator.mediaSession.metadata = new MediaMetadata({
            title: track.title || 'Unknown title',
            artist: track.artist_name || 'Unknown artist',
            album: track.album_name || 'MaxTune',
          })
        } catch {
          // ignore
        }
      }
      this.syncMediaSessionPlaybackState()
      this.updateMediaSessionPosition()
    },

    syncMediaSessionPlaybackState() {
      if (!hasMediaSession()) return
      try {
        if (!this.currentTrack) {
          navigator.mediaSession.playbackState = 'none'
        } else {
          navigator.mediaSession.playbackState = this.isPlaying ? 'playing' : 'paused'
        }
      } catch {
        // ignore
      }
    },

    updateMediaSessionPosition() {
      if (!hasMediaSession() || typeof navigator.mediaSession.setPositionState !== 'function') return
      const audio = getAudio()
      const duration = audio?.duration
      if (!duration || !Number.isFinite(duration) || duration <= 0) return
      try {
        navigator.mediaSession.setPositionState({
          duration,
          playbackRate: audio.playbackRate || 1,
          position: Math.min(duration, Math.max(0, audio.currentTime || 0)),
        })
      } catch {
        // ignore invalid position state
      }
    },

    /**
     * @param {object} track
     * @returns {Promise<boolean>}
     */
    async playFromLocal(track) {
      const offline = useOfflineStore()
      const blobUrl = await offline.getLocalBlobUrl(track.id)
      if (!blobUrl) return false

      this.bindAudioEvents()
      const audio = getAudio()
      if (!audio) return false

      // Revoke previous track blob URL if switching away
      if (this.currentTrack?.id && this.currentTrack.id !== track.id && this.playingFromLocal) {
        offline.revokeBlobUrl(this.currentTrack.id)
      }

      this.error = null
      this.playingFromLocal = true
      this.currentTrack = track
      this.positionMs = 0
      this.durationMs = track.duration_ms || 0
      this.updateMediaSessionMetadata()

      audio.src = blobUrl
      audio.load()

      try {
        await audio.play()
        this.isPlaying = true
        this.syncMediaSessionPlaybackState()
        return true
      } catch (err) {
        this.isPlaying = false
        this.error = err?.message || 'Could not start playback'
        this.syncMediaSessionPlaybackState()
        return false
      }
    },

    /**
     * @param {object} track
     * @param {object[]} [queue]
     */
    async playTrack(track, queue) {
      this.bindAudioEvents()
      const audio = getAudio()
      if (!audio) return

      if (Array.isArray(queue)) {
        this.queue = queue
      }

      fallbackAttemptedFor = null
      this.error = null

      const offline = useOfflineStore()
      await offline.hydrate()

      const preferLocal = isBrowserOrEngineOffline()

      if (preferLocal) {
        if (offline.isDownloaded(track.id)) {
          const ok = await this.playFromLocal(track)
          if (ok) return
        }
        notifyPlayOffline()
        this.error = OFFLINE_COPY.err.playOffline
        // Keep previous track if any; else clear current selection without spinning
        if (!this.currentTrack || this.currentTrack.id === track.id) {
          // Still set current for UI context but do not load remote
          this.currentTrack = track
          this.isPlaying = false
          this.playingFromLocal = false
        }
        this.syncMediaSessionPlaybackState()
        return
      }

      const streamUrl = toEngineProxyUrl(track.stream_url)
      if (!streamUrl) {
        // Try local as last resort
        if (offline.isDownloaded(track.id)) {
          const ok = await this.playFromLocal(track)
          if (ok) return
        }
        this.error = 'No stream URL for this track'
        return
      }

      // Revoke previous local URL when switching to network
      if (this.currentTrack?.id && this.playingFromLocal) {
        offline.revokeBlobUrl(this.currentTrack.id)
      }

      this.playingFromLocal = false
      this.currentTrack = track
      this.positionMs = 0
      this.durationMs = track.duration_ms || 0
      this.updateMediaSessionMetadata()

      const absolute = new URL(streamUrl, window.location.origin).href
      if (audio.src !== absolute) {
        audio.src = streamUrl
        audio.load()
      }

      try {
        await audio.play()
        this.isPlaying = true
        this.syncMediaSessionPlaybackState()
      } catch (err) {
        // Network play failed — try local once
        if (offline.isDownloaded(track.id)) {
          fallbackAttemptedFor = String(track.id)
          const ok = await this.playFromLocal(track)
          if (ok) return
        }
        this.isPlaying = false
        this.error = err?.message || 'Could not start playback'
        this.syncMediaSessionPlaybackState()
      }
    },

    /**
     * @param {object[]} tracks
     * @param {number} [startIndex]
     */
    async playQueue(tracks, startIndex = 0) {
      if (!tracks?.length) return
      const idx = Math.min(Math.max(0, startIndex), tracks.length - 1)
      await this.playTrack(tracks[idx], tracks)
    },

    queueIndex() {
      if (!this.currentTrack || !this.queue.length) return -1
      return this.queue.findIndex((t) => t.id === this.currentTrack.id)
    },

    /**
     * @param {{ auto?: boolean }} [opts]
     */
    async playNext(opts = {}) {
      const idx = this.queueIndex()
      if (idx < 0 || !this.queue.length) return

      if (idx < this.queue.length - 1) {
        await this.playTrack(this.queue[idx + 1], this.queue)
        return
      }

      if (this.repeat === 'all') {
        await this.playTrack(this.queue[0], this.queue)
        return
      }

      if (!opts.auto) {
        // stay on last track when user hits next
      }
    },

    async playPrev() {
      const audio = getAudio()
      if (audio && audio.currentTime > 3) {
        audio.currentTime = 0
        this.positionMs = 0
        this.updateMediaSessionPosition()
        return
      }

      const idx = this.queueIndex()
      if (idx > 0) {
        await this.playTrack(this.queue[idx - 1], this.queue)
      } else if (audio) {
        audio.currentTime = 0
        this.positionMs = 0
        this.updateMediaSessionPosition()
      }
    },

    async resumeFromMediaSession() {
      if (!this.currentTrack) return
      this.bindAudioEvents()
      const audio = getAudio()
      if (!audio) return

      if (audio.paused && audio.src) {
        try {
          await audio.play()
        } catch (err) {
          this.error = err?.message || 'Could not resume'
        }
        return
      }

      if (!audio.src) {
        await this.playTrack(this.currentTrack)
      }
    },

    async togglePlay() {
      if (!this.currentTrack) return
      this.bindAudioEvents()
      const audio = getAudio()
      if (!audio) return

      if (this.isPlaying) {
        audio.pause()
        return
      }

      if (!audio.src) {
        await this.playTrack(this.currentTrack)
        return
      }

      try {
        await audio.play()
      } catch (err) {
        this.error = err?.message || 'Could not resume'
      }
    },

    /**
     * @param {number} pct 0–100
     */
    seekPct(pct) {
      const audio = getAudio()
      if (!audio || !audio.duration) return
      const clamped = Math.min(100, Math.max(0, pct))
      audio.currentTime = (clamped / 100) * audio.duration
      this.positionMs = Math.round(audio.currentTime * 1000)
      this.updateMediaSessionPosition()
    },

    /**
     * @param {number} value 0–1
     */
    setVolume(value) {
      this.volume = Math.min(1, Math.max(0, value))
      const audio = getAudio()
      if (audio) audio.volume = this.volume
    },

    clear() {
      const audio = getAudio()
      const offline = useOfflineStore()
      if (this.currentTrack?.id && this.playingFromLocal) {
        offline.revokeBlobUrl(this.currentTrack.id)
      }
      if (audio) {
        audio.pause()
        audio.removeAttribute('src')
        audio.load()
      }
      this.currentTrack = null
      this.queue = []
      this.isPlaying = false
      this.playingFromLocal = false
      this.positionMs = 0
      this.durationMs = 0
      this.error = null
      this.sheetOpen = false
      fallbackAttemptedFor = null
      this.updateMediaSessionMetadata()
    },
  },
})
